	/**
	 * Default Constructor
	 */
    public DashboardService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new DashboardEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(DashboardRepository.class) );
		this.validator		= applicationContext.getBean(DashboardValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Dashboard
	 */
		public Dashboard createDashboard( CreateDashboardCommand command ) {

		Dashboard entity = new Dashboard();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setDashboardId( command.getDashboardId() );
            entity.setTitle( command.getTitle() );
            entity.setTheme( command.getTheme() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Dashboard {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateDashboardCommand
	 * @return		Dashboard
	 */
	public Dashboard updateDashboard( UpdateDashboardCommand command ) {

		Dashboard entity = new Dashboard();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setDashboardId( command.getDashboardId() );
            entity.setTitle( command.getTitle() );
            entity.setTheme( command.getTheme() );
            entity.setWorkspace( command.getWorkspace() );
            entity.setVisualizations( command.getVisualizations() );
            entity.setReports( command.getReports() );
            entity.setDatasets( command.getDatasets() );
            entity.setAlerts( command.getAlerts() );
            entity.setQueries( command.getQueries() );
            entity.setTags( command.getTags() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Dashboard {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteDashboardCommand
	 */
	public void delete( DeleteDashboardCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getDashboardId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Dashboard {0} ", id );

	}

	/**
	 * Method to retrieve the Dashboard via DashboardFetchOneSummary
	 * @param 	summary DashboardFetchOneSummary
	 * @return 	DashboardFetchOneResponse
	 */
	public Dashboard getDashboard( DashboardFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "DashboardFetchOneSummary arg cannot be null" );

		Dashboard entity = null;
		UUID id = summary.getDashboardId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Dashboard using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Dashboards
	 *
	 * @return 	List<Dashboard>
	 */
    public List<Dashboard> getAllDashboard() {
		List<Dashboard> list = projector.findAll( new FindAllDashboardQuery() );
		return list;
	}

	/**
	 * assign Workspace on Dashboard
	 * @param		command AssignWorkspaceToDashboardCommand
	 */
	public void assignWorkspace( AssignWorkspaceToDashboardCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignWorkspace(command.getDashboardId(), command.getAssignment());

	}

